page.script:
// 触发事件
function CrrHandler(t) {
	// 保存&更新事件
	if (t.id == "save") {
		if (Ext.getCmp('materielForm').getForm().isValidCux()) {
			var data = Ext.getCmp("materielForm").getForm().getValues();
			var url = "/webapi/archives/materiel/add";
			if (data.id != null && data.id != "") {
				url = "/webapi/archives/materiel/edit";
			}
			post(url, data, function(res) {
				Ext.MessageBox.alert("提示", res.msg);
				Ext.getCmp('materielList').getStore().load();
				Ext.getCmp('materielFormWin').close();
			});
		}
	}
}
// 产品分类赋值
function setProductClass(data) {
	Ext.getCmp("materielForm").getForm().findField("productClassNo").setValue(data.productClassNo);
}
// 获取产品分类值
function getProductClass() {
	var form = Ext.getCmp("materielForm").getForm();
	var data = {
		productClassNo: form.findField("productClassNo").getValue()
	}
	return data;
}
// 牌号档案列表
function chooseSkuFile() {
	var data = {confirm: "skuFileConfirm"};
	handleRoute("ChooseSkuFile", data);
}
// 牌号档案确定事件
function skuFileConfirm(data) {
	var form = Ext.getCmp("materielForm").getForm();
	form.findField("skuNo").setValue(data.skuNo);
	form.findField("skuName").setValue(data.skuName);
	form.findField("executiveStandard").setValue(data.executiveStandard);
	form.findField("standardNumber").setValue(data.standardNumber);
}
// ERP产品列表
function chooseErpMateriel() {
	var data = {confirm: "erpMaterielConfirm"};
	handleRoute("ChooseErpMateriel", data);
}
// ERP产品确定事件
function erpMaterielConfirm(data) {
	var form = Ext.getCmp("materielForm").getForm();
	form.findField("erpMaterielNo").setValue(data.erpMaterielNo);
	form.findField("erpMaterielName").setValue(data.erpMaterielName);
	form.findField("erpMaterielShowdesc").setValue(data.erpMaterielShowdesc);
}
